pub async fn run_events(p: Path<String>) -> Response {
    let run_id: String = path_inner(&p);
    let sub = relay_bus_subscribe(&run_id);
    let stream = run_events_stream(sub.clone());
    let mut sse = Sse::new(stream);
    return sse.keep_alive(KeepAlive::new()).into_response();
}

/// GET /api/forge/relay/runs/{run_id}/events — SSE 流(run 事件,按 run_id 过滤)。
fn run_events_stream(sub: RelaySub) -> impl futures::Stream<Item = Result<Event, Infallible>> { async_stream::stream! {{
    loop {
        let msg = relay_sub_recv(&sub).await;
        if msg_is_none(&msg) {
            

            break;
        } else {
            let ev = msg_unwrap(msg);
            let ev_type: String = value_get_str(&ev, "event_type");
            let payload: Value = value_get(&ev, "payload");
            let frame = RunEventFrame { event_type: ev_type.to_string(), payload: payload };
            // PLAN-030 试用修复：未命名事件（onmessage 兼容）——具名事件
            // EventSource.onmessage 收不到，RunBox 实时更新全链路失效。
            let event = sse_plain_event(to_value(frame).unwrap());
            yield Ok(event);
        }

    }
} } }

