pub async fn resolve_gate(s: State<AppState>, p: Path<String>, q: Query<WorkspaceQuery>, body: Json<ResolveGateBody>) -> Response {
    let run_id: String = path_inner(&p);
    let decision: String = body.decision.clone();
    if decision != "approve" {
        if decision != "edit" {
            if decision != "reject" {
                return text_response(format!("{}{}", format!("{}{}", "unknown gate decision '", decision), "' (want approve|reject|edit)").as_str(), 400);
            }        }    }
    let mut feedback: String = "".to_string();


    match body.feedback.clone() {
        Some(f) => feedback = f,
        None => {},
    };
    let resp: Value = relay_resolve_gate(&s, q, &run_id, &decision, &feedback);
    if value_is_null(&resp) {
        return text_response(format!("{}{}", format!("{}{}", "run '", run_id), "' not found").as_str(), 404);
    }
    return ok_response(resp);
}

